head.script:
scwin.onpageload = function() {
	windowContainer1.createWindow({
		"title" : "Green", 
		"src" : "WindowContainer_wframe_scheduleCalendar_WESE-1049_(WSQ-5959)_sub.xml", 
		"windowId" : "window1", 
		"frameMode" : "wframe"
	});    
	windowContainer1.createWindow({
		"title" : "Blue", 
		"src" : "WindowContainer_wframe_scheduleCalendar_WESE-1049_(WSQ-5959)_sub.xml", 
		"windowId" : "window2", 
		"frameMode" : "wframe"
	});
	windowContainer1.createWindow({
		"title" : "yellow", 
		"src" : "WindowContainer_wframe_scheduleCalendar_WESE-1049_(WSQ-5959)_sub.xml", 
		"windowId" : "window3", 
		"frameMode" : "wframe"
	});
	windowContainer1.createWindow({
		"title" : "red", 
		"src" : "WindowContainer_wframe_scheduleCalendar_WESE-1049_(WSQ-5959)_sub.xml", 
		"windowId" : "window4", 
		"frameMode" : "wframe"
	});	
};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return document.getElementsByClassName('fc-scrollgrid-sync-table')[2].style.width != '0px';
}
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_nameLayer_mf_windowContainer1_subWindow2').click()");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
